#!/bin/bash

# Generated by the PhyloPhere runner GUI. Edit the project file and regenerate
# instead of editing this file, unless the change is a one-off.
#
# profile 'slurm': submit with `sbatch`. SLURM sets SLURM_ARRAY_TASK_ID for each
# array task and dispatch_phenotype below reads it once.
# profile 'local': run with `bash`. There is no scheduler and no SLURM_ARRAY_TASK_ID,
# so the script loops over every phenotype row itself, one after another.


# ── Environment activation ────────────────────────────────────────────────────
# Activates the phylophere environment with micromamba, or with conda when micromamba
# is absent. nounset is off while the activation hooks run.
set +u
if command -v micromamba >/dev/null 2>&1; then
    eval "$(micromamba shell hook --shell bash)"
    micromamba activate phylophere
elif [ -n "${CONDA_EXE:-}" ] || command -v conda >/dev/null 2>&1; then
    __base="$(conda info --base 2>/dev/null || dirname "$(dirname "${CONDA_EXE:-}")")"
    [ -f "$__base/etc/profile.d/conda.sh" ] && . "$__base/etc/profile.d/conda.sh"
    conda activate phylophere
fi
set -u

# ── Global run configuration ──────────────────────────────────────────────────
export RESUME="${RESUME:-0}"
export RUN_TOWER=false
export REMOVE_WORK="${REMOVE_WORK:-false}"

if [ "false" = true ]; then
    export TAG="_toy"
    export TOY_MODE=true
    export TOY_N=""
    export CAAS_FULL_PERMS="100"
    # The permulation draw budget scales with the toy harvest target (CAAS_FULL_PERMS)
    # instead of keeping the full-run value. Toy mode subsamples alignments, never
    # species, so permulation runs on the full tree at the full acceptance rate: 100
    # accepted draws need well under 1k draws even under BM, and 200 draws per cycle
    # (200 with no cycle) leave ample headroom. The cap also bounds a run that cannot
    # fill the pool to about a minute, where the full-run budget would spend 1M draws
    # plus two escalations before failing, which would defeat a smoke test.
    export MAX_TRIES="$(( CAAS_FULL_PERMS > 0 ? CAAS_FULL_PERMS * 200 : 200 ))"
else
    export TAG=""
    export TOY_MODE=false
    export TOY_N=""
    export CAAS_FULL_PERMS="${CAAS_FULL_PERMS:-1000}"
    export MAX_TRIES="10000"
fi
# RERconverge permulations: the values of the RERconverge tab, in toy mode too.
